#!/bin/bash
# Per-image caption isolation test, keeping rank16/attn-only capacity
# fixed (2026-08-07 user direction: try a different angle at rank16
# rather than raising capacity further -- the hicap rank32+conv run
# regressed on every structural/macro axis instead of improving them).
#
# Same setup as domain_lora_line_sd15base_20260806 (SD1.5 base, rank16,
# attention-only LoRA, same 1489-image line_combined_koma_20260729 pool,
# same 10 epochs) except every training image now gets its own caption
# instead of one fixed caption repeated for all 1489 images. Captions
# generated by scripts/tag_wd14.py (WD14 anime tagger, already built for
# the ControlNet Direction 4 work) -- danbooru-style per-tile tags
# (composition/content: white_background, simple_background, close-up,
# chibi, 1girl, etc.) plus the same style suffix used everywhere else in
# this project ("lineartstyle, monochrome line art, clean linework, manga
# panel, black and white"), so the style anchor is unchanged and only the
# content-specification signal is added. Rationale: the rough-domain
# caption motif test (2026-08-06) showed content-recognizability broke
# immediately once the caption specified a subject -- but that was tested
# only as a sampling-time prompt override on an already-trained,
# generic-caption checkpoint. This run tests the deeper version: does
# training itself with per-image content captions (rather than one
# repeated caption) let the LoRA spend its weights on style/stroke
# fidelity instead of on absorbing uncaptioned content variance -- which
# is a plausible reason none of the base/capacity variants so far matched
# our tiles' composition even under the fixed generic caption.
#
# Sampling still uses the single generic style caption (same as every
# prior line-domain run) for direct comparability -- this isolates
# whether TRAINING-time per-image captions change the model's default/
# unprompted composition habit, not just prompt-time content steering.
set -euo pipefail
cd "$(dirname "$0")/.."

PY=./venv/bin/python
TAG=domain_lora_line_sd15base_captiontags_20260807
EPOCHS=${EPOCHS:-10}
LORA_RANK=${LORA_RANK:-16}
CAPTION="lineartstyle, monochrome line art, clean linework, manga panel, black and white"
CAPTION_CSV="results/domain_lora_line_captiontags_20260807/tags.csv"
IMAGE_DIRS="dataset/pairs_480/train/line_combined_koma_20260729"
BASE_CKPT=$HOME/disk/checkpoint/Stable-diffusion/v1-5-pruned-emaonly.safetensors

LOG=logs/${TAG}.log
DONE=logs/${TAG}.done
CKPT=checkpoints/${TAG}

mkdir -p logs checkpoints
: > "$LOG"
exec > >(tee -a "$LOG") 2>&1

echo "[$(date --iso-8601=seconds)] domain_lora line-domain sd15-base captiontags start (epochs=$EPOCHS rank=$LORA_RANK base=$BASE_CKPT captions=$CAPTION_CSV)"

"$PY" scripts/train_domain_lora.py \
  --image-dirs $IMAGE_DIRS \
  --output-dir "$CKPT" \
  --caption "$CAPTION" \
  --caption-csv "$CAPTION_CSV" \
  --lora-rank "$LORA_RANK" \
  --epochs "$EPOCHS" \
  --base-ckpt "$BASE_CKPT"

echo "=== sample + contact sheet ==="
"$PY" scripts/sample_domain_lora.py \
  --lora-dir "$CKPT/final" \
  --caption "$CAPTION" \
  --base-ckpt "$BASE_CKPT" \
  --tag "$TAG" \
  --num-samples 16

{
  echo "completed_at=$(date --iso-8601=seconds)"
  echo "tag=$TAG"
  echo "epochs=$EPOCHS"
  echo "lora_rank=$LORA_RANK"
  echo "caption_csv=$CAPTION_CSV"
  echo "base_ckpt=$BASE_CKPT"
  echo "checkpoint=$CKPT/final"
  echo "contact_sheet=results/${TAG}/contact_sheet_${TAG}.png"
} > "$DONE"

experiments/send_autoloop_notification.sh \
  "Lineart domain LoRA (line domain, SD1.5 base, per-image captions) training complete" \
  "Review results/${TAG}/contact_sheet_${TAG}.png" || true

echo "done marker: $DONE"
echo "[$(date --iso-8601=seconds)] domain_lora line-domain sd15-base captiontags complete"
